/**
 * Return the port if the request should be proxied. Anything that ends in a
 * proxy domain and has a *single* subdomain should be proxied. Anything else
 * should return `undefined` and will be handled as normal.
 *
 * For example if `coder.com` is specified `8080.coder.com` will be proxied
 * but `8080.test.coder.com` and `test.8080.coder.com` will not.
 */
export const maybeProxy = (req: Request): string | undefined => {
  // Split into parts.
  const host = req.headers.host || ""
  const idx = host.indexOf(":")
  const domain = idx !== -1 ? host.substring(0, idx) : host

  // `VSCODE_PROXY_URI` can use a port in any part of its hostname, not just
  // as a subdomain.  This lets deployments use names such as
  // `{{port}}-code.example.com`.
  const proxyUri = process.env.VSCODE_PROXY_URI
  if (proxyUri) {
    try {
      const hostname = new URL(proxyUri).hostname
      const placeholder = "{{port}}"
      const placeholderIndex = hostname.indexOf(placeholder)
      if (placeholderIndex !== -1 && hostname.indexOf(placeholder, placeholderIndex + placeholder.length) === -1) {
        const escapeRegex = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
        const pattern = new RegExp(
          `^${escapeRegex(hostname.slice(0, placeholderIndex))}(\\d+)${escapeRegex(
            hostname.slice(placeholderIndex + placeholder.length),
          )}$`,
          "i",
        )
        const match = domain.match(pattern)
        if (match) {
          return match[1]
        }
      }
    } catch {
      // Relative proxy URIs do not have a hostname and continue to use the
      // path-based proxy.
    }
  }

  const parts = domain.split(".")

  // There must be an exact match.
  const port = parts.shift()
  const proxyDomain = parts.join(".")
  if (!port || !req.args["proxy-domain"].includes(proxyDomain)) {
    return undefined
  }

  return port
}

